# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">PHYSICAL AND MENTAL WELL-BEING &amp; DAILY HABITS (ENG.10.3)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#1e40af">PHYSICAL HEALTH &amp; NUTRITION HABITS</text>\n  <text x="35" y="88" font-size="11.1" fill="#1e3a8a">• keep fit / work out regularly (düzenli egzersiz)</text>\n  <text x="35" y="112" font-size="11.1" fill="#1e3a8a">• have a balanced and nutritious diet (dengeli diyet)</text>\n  <text x="35" y="136" font-size="11.1" fill="#1e3a8a">• stay hydrated / get enough sleep (yeterli uyku)</text>\n  <text x="35" y="160" font-size="11.1" fill="#1e3a8a">• cut down on junk food &amp; sugary drinks</text>\n  <text x="35" y="184" font-size="11.1" fill="#1e3a8a">• strengthen the immune system (bağışıklığı güçlendirme)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#166534">MENTAL WELL-BEING &amp; STRESS MANAGEMENT</text>\n  <text x="370" y="88" font-size="11.1" fill="#14532d">• cope with stress and anxiety (stresle başa çıkma)</text>\n  <text x="370" y="112" font-size="11.1" fill="#14532d">• digital detox / limit screen time (ekran süresini kısma)</text>\n  <text x="370" y="136" font-size="11.1" fill="#14532d">• mindfulness &amp; relaxation techniques</text>\n  <text x="370" y="160" font-size="11.1" fill="#14532d">• maintain work-life / study-life balance</text>\n  <text x="370" y="184" font-size="11.1" fill="#14532d">• overcome burnout and mental fatigue</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">A healthy lifestyle requires harmony between physical fitness, balanced nutrition, and mental peace.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">GIVING ADVICE AND WARNINGS: SHOULD / OUGHT TO / HAD BETTER</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#92400e">SHOULD &amp; OUGHT TO (GENERAL ADVICE)</text>\n  <text x="35" y="88" font-size="11.1" fill="#78350f">• Yapı: should / shouldn\'t + V₁ (yalın fiil)</text>\n  <text x="35" y="112" font-size="11.1" fill="#78350f">• Yapı: ought to / ought not to + V₁</text>\n  <text x="35" y="136" font-size="11.1" fill="#78350f">• İşlev: Genel tavsiye, öneri ve doğru olanı</text>\n  <text x="45" y="152" font-size="10.8" fill="#78350f">hatırlatma ("-meli / -malı").</text>\n  <text x="35" y="176" font-size="10.8" fill="#78350f">• Örnek: You should drink plenty of water.</text>\n  <text x="35" y="196" font-size="10.8" fill="#78350f">• Örnek: We ought to exercise three times a week.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#6b21a8">HAD BETTER (STRONG ADVICE &amp; WARNING)</text>\n  <text x="370" y="88" font-size="11.1" fill="#581c87">• Yapı: had better (\'d better) + V₁ (yalın fiil!)</text>\n  <text x="370" y="112" font-size="11.1" fill="#581c87">• Olumsuz: had better not + V₁ (\'to\' ALMAZ!)</text>\n  <text x="370" y="136" font-size="11.1" fill="#581c87">• İşlev: Özel ve acil durumlarda güçlü tavsiye;</text>\n  <text x="380" y="152" font-size="10.8" fill="#581c87">yapılmazsa kötü bir sonuç doğacağını uyarır.</text>\n  <text x="370" y="176" font-size="10.8" fill="#581c87">• Örnek: You had better see a dentist today.</text>\n  <text x="370" y="196" font-size="10.8" fill="#581c87">• Örnek: You\'d better not skip breakfast.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Dikkat: \'had better\' yapısında \'had\' geçmesine rağmen anlam geçmiş zaman değil, ŞİMDİ ve GELECEK zamandır!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">EXPRESSING CONSEQUENCES, CAUSE &amp; EFFECT IN WELL-BEING</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#9a3412">WARNING + OTHERWISE / OR ELSE</text>\n  <text x="35" y="88" font-size="11.1" fill="#7c2d12">• Tavsiye cümlesinin ardından \'aksi takdirde /</text>\n  <text x="45" y="104" font-size="10.8" fill="#7c2d12">yoksa\' anlamında olası sonucu bildirir:</text>\n  <text x="35" y="128" font-size="10.8" fill="#7c2d12">• You had better get enough sleep; otherwise,</text>\n  <text x="45" y="144" font-size="10.8" fill="#7c2d12">you will feel exhausted during the exam.</text>\n  <text x="35" y="168" font-size="10.8" fill="#7c2d12">• You should reduce screen time, or else you</text>\n  <text x="45" y="184" font-size="10.8" fill="#7c2d12">may suffer from severe eye strain and insomnia.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#065f46">CONSEQUENCE LINKERS &amp; CONDITIONALS</text>\n  <text x="370" y="88" font-size="11.1" fill="#064e3b">• Therefore / As a result / Consequently:</text>\n  <text x="380" y="104" font-size="10.8" fill="#064e3b">("Bu yüzden / Sonuç olarak" — sonuç cümlesi)</text>\n  <text x="370" y="128" font-size="11.1" fill="#064e3b">• Lead to / Result in / Cause + Noun / V-ing:</text>\n  <text x="380" y="144" font-size="10.8" fill="#064e3b">("...ya yol açmak / sebep olmak")</text>\n  <text x="370" y="168" font-size="11.1" fill="#064e3b">• First Conditional (If / Unless + Present, Will):</text>\n  <text x="380" y="184" font-size="10.8" fill="#064e3b">If you eat balanced meals, you will stay energetic.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Unless (= If ... not): "Unless you change your sedentary lifestyle, you will face health problems."</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
